                repos are exactly where KainBain traces must stay out. The
                toggle names the option so it stays findable when collapsed. */}
            <div>
              <button
                type="button"
                onClick={() => setAdoptAdvancedOpen((open) => !open)}
                aria-expanded={adoptAdvancedOpen}
                aria-controls="adopt-project-advanced"
                className="text-[11px] font-bold uppercase tracking-widest text-text-muted hover:text-on-surface cursor-pointer flex items-center gap-1"
              >
                <span
                  className={`material-symbols-outlined text-base transition-transform ${adoptAdvancedOpen ? 'rotate-90' : ''}`}
                  aria-hidden="true"
                >
                  chevron_right
                </span>
                Advanced options: separate docs repo
              </button>
              {adoptAdvancedOpen && (
                <div id="adopt-project-advanced" className="mt-3">
                  <DocsRepoFields
                    docsRepoUrl={adoptDocsRepoUrl}
                    setDocsRepoUrl={setAdoptDocsRepoUrl}
                    docsRepoLocalPath={adoptDocsRepoPath}
                    setDocsRepoLocalPath={setAdoptDocsRepoPath}
                    showLocalPath
                  />
                </div>
              )}
            </div>

            {adoptError && (
              <p role="alert" className="text-xs text-error">
                {adoptError}
              </p>
            )}

            <div className="flex justify-end gap-3 pt-4 border-t border-border-standard">
              <button
                type="button"
                onClick={closeAdoptProjectModal}
                className="px-4 py-2 bg-surface-container-high hover:bg-surface-container-highest text-on-surface-variant text-xs font-bold uppercase tracking-widest rounded-sm transition-colors cursor-pointer"
              >
                Cancel
              </button>
              <button
                type="submit"
                disabled={!adoptPath.trim()}
                className="px-6 py-2 bg-primary text-on-primary text-xs font-bold uppercase tracking-widest rounded-sm hover:brightness-110 transition-all active:scale-95 disabled:opacity-40 cursor-pointer"
              >
                Add Project
              </button>
            </div>
          </form>
        </Modal>
      )}
    </>
  );
}
