269|    >
270|      {/* Top section switcher (tabs left, settings search right) */}
271|      <div className="flex gap-2 justify-between items-center border-b border-border-standard pb-4">
272|        <div className="flex gap-2 flex-wrap" role="tablist" aria-label="Project settings sections">
